"use client";

import { memo, useEffect, useRef, type ComponentProps } from "react";
import { useReducedMotion, useSpring } from "motion/react";
import { createShaderRenderer } from "./shader-renderer.shared";
import { cn } from "cn";
import topoShader from "./topographic-contour-map.wgsl";

type Color = readonly [number, number, number];
const defaultBackground: Color = [0.012, 0.012, 0.012];
const palettes = {
  studio: [
    [0.157, 0.235, 0.275],
    [0.392, 0.706, 0.824],
    [0.627, 0.863, 1],
  ],
  amber: [
    [1, 0.549, 0.314],
    [1, 0.745, 0.471],
    [1, 0.902, 0.706],
  ],
  teal: [
    [0.392, 1, 0.941],
    [0.588, 1, 0.961],
    [0.784, 1, 1],
  ],
  violet: [
    [0.706, 0.549, 1],
    [0.824, 0.706, 1],
    [0.941, 0.863, 1],
  ],
} as const;

export interface TopographicContourMapProps extends Omit<ComponentProps<"div">, "color"> {
  color?: Color;
  colorScheme?: keyof typeof palettes;
  mouseInfluence?: boolean;
  showLabels?: boolean;
  fadeLeft?: boolean;
  backgroundColor?: Color;
  scale?: number;
  density?: number;
  lineWidth?: number;
  speed?: number;
}

export const TopographicContourMap = memo(function TopographicContourMap({
  color,
  colorScheme = "amber",
  mouseInfluence = true,
  showLabels = true,
  fadeLeft = true,
  backgroundColor = defaultBackground,
  scale = 3,
  density = 24,
  lineWidth = 1,
  speed = 0.08,
  className,
  ...props
}: TopographicContourMapProps = {}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hostRef = useRef<HTMLDivElement>(null);
  const reducedMotion = useReducedMotion();
  const hover = useSpring(0, { stiffness: 140, damping: 24 });
  const press = useSpring(0, { stiffness: 140, damping: 24 });
  const selected = palettes[colorScheme];
  const zoom = Number.isFinite(scale) ? Math.max(0.1, scale) : 3;
  const levels = Number.isFinite(density) ? Math.min(100, Math.max(2, density)) : 24;
  const width = Number.isFinite(lineWidth) ? Math.min(8, Math.max(0.25, lineWidth)) : 1;
  const rate = Number.isFinite(speed) ? Math.max(0, speed) : 0.08;
  const [r, g, b] = (color ?? selected[1]).map((channel) =>
    Number.isFinite(channel) ? Math.max(0, Math.min(1, channel)) : 0,
  );
  const [br, bg, bb] = backgroundColor.map((channel) =>
    Number.isFinite(channel) ? Math.max(0, Math.min(1, channel)) : 0,
  );

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const host = hostRef.current;
    let pointer = [0.5, 0.5, 0, 0];
    const track = (event: PointerEvent) => {
      if (!mouseInfluence || reducedMotion || event.pointerType === "touch" || !host) return;
      const rect = host.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      pointer[0] = (event.clientX - rect.left) / rect.width;
      pointer[1] = (event.clientY - rect.top) / rect.height;
      hover.set(1);
    };
    const leave = () => {
      hover.set(0);
      press.set(0);
    };
    const down = (event: PointerEvent) => {
      track(event);
      if (event.button === 0 && event.pointerType !== "touch") press.set(1);
    };
    const up = () => {
      press.set(0);
    };
    host?.addEventListener("pointermove", track);
    host?.addEventListener("pointerleave", leave);
    host?.addEventListener("pointercancel", leave);
    host?.addEventListener("pointerdown", down);
    window.addEventListener("pointerup", up);
    const cleanup = () => {
      host?.removeEventListener("pointermove", track);
      host?.removeEventListener("pointerleave", leave);
      host?.removeEventListener("pointercancel", leave);
      host?.removeEventListener("pointerdown", down);
      window.removeEventListener("pointerup", up);
      hover.jump(0);
      press.jump(0);
      renderer.dispose();
    };
    const renderer = createShaderRenderer(canvas, topoShader, {
      label: "topographic-contour-map",
      fps: 30,
      animated: !reducedMotion && (rate > 0 || mouseInfluence),
      uniforms: (time, size) => {
        pointer = [
          pointer[0],
          pointer[1],
          reducedMotion ? 0 : hover.get(),
          reducedMotion ? 0 : press.get(),
        ];
        return {
          cfg: {
            metrics: [size[0], size[1], zoom, time * rate],
            contours: [levels, width, 0, 0],
            pointer,
            options: [Number(showLabels), Number(fadeLeft), 0, 0],
            low: [...(color ? [r * 0.5, g * 0.5, b * 0.5] : selected[0]), 1],
            high: [
              ...(color
                ? [Math.min(1, r * 1.3), Math.min(1, g * 1.3), Math.min(1, b * 1.3)]
                : selected[2]),
              1,
            ],
            foreground: [r, g, b, 1],
            background: [br, bg, bb, 1],
          },
        };
      },
    });
    return cleanup;
  }, [
    zoom,
    levels,
    width,
    rate,
    r,
    g,
    b,
    br,
    bg,
    bb,
    reducedMotion,
    mouseInfluence,
    showLabels,
    fadeLeft,
    selected,
    color,
    hover,
    press,
  ]);

  return (
    <div
      {...props}
      ref={hostRef}
      data-slot="topographic-contour-map"
      className={cn(
        " relative isolate min-h-96 overflow-hidden border border-border",
        className,
      )}
    >

        <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full opacity-0" />

    </div>
  );
});

import { lightBlue, lightEmerald, lightGold, lightInk, lightPaper } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  metrics: vec4f, // width, height, terrain scale, time
  contours: vec4f, // density, line width, reserved
  pointer: vec4f, // normalized position, influence, press strength
  options: vec4f, // reserved (was labels), left fade, reserved
  low: vec4f,
  foreground: vec4f,
  high: vec4f,
  background: vec4f,
};
@group(0) @binding(0) var<uniform> cfg: Config;

fn hash(p: vec3f) -> f32 {
  return fract(sin(dot(p, vec3f(127.1, 311.7, 74.7))) * 43758.5453);
}

fn noise(p: vec3f) -> f32 {
  let cell = floor(p);
  let f = fract(p);
  let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  let a = mix(mix(hash(cell), hash(cell + vec3f(1, 0, 0)), u.x),
    mix(hash(cell + vec3f(0, 1, 0)), hash(cell + vec3f(1, 1, 0)), u.x), u.y);
  let b = mix(mix(hash(cell + vec3f(0, 0, 1)), hash(cell + vec3f(1, 0, 1)), u.x),
    mix(hash(cell + vec3f(0, 1, 1)), hash(cell + vec3f(1, 1, 1)), u.x), u.y);
  return mix(a, b, u.z);
}

fn terrain(pixel: vec2f) -> f32 {
  let p = pixel / cfg.metrics.y * cfg.metrics.z + vec2f(4.7, 9.2);
  var height = noise(vec3f(p, cfg.metrics.w)) * 0.57;
  height += noise(vec3f(p * 2.0 + vec2f(11.3), cfg.metrics.w * 0.8)) * 0.29;
  height += noise(vec3f(p * 4.0 + vec2f(27.8), cfg.metrics.w * 0.6)) * 0.14;
  let distance = length(pixel - cfg.pointer.xy * cfg.metrics.xy);
  let radius = min(cfg.metrics.x, cfg.metrics.y) * 0.35;
  let influence = pow(max(0.0, 1.0 - distance / radius), 2.0);
  return (height - 0.2) * 1.65 + influence * cfg.pointer.z * mix(0.32, -0.32, cfg.pointer.w);
}

fn palette(height: f32) -> vec3f {
  let h = clamp(height, 0.0, 1.0);
  return mix(mix(cfg.low.rgb, cfg.foreground.rgb, min(h * 2.0, 1.0)),
    cfg.high.rgb, max(h * 2.0 - 1.0, 0.0));
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let pixel = uv * cfg.metrics.xy;
  let height = terrain(pixel);
  let level = height * cfg.contours.x;
  let distance = abs(fract(level + 0.5) - 0.5) / max(fwidth(level), 0.0001);
  let line = 1.0 - smoothstep(cfg.contours.y * 0.35, cfg.contours.y * 0.35 + 0.8, distance);
  let majorLevel = level / 4.0;
  let majorDistance = abs(fract(majorLevel + 0.5) - 0.5) / max(fwidth(majorLevel), 0.0001);
  let major = 1.0 - smoothstep(cfg.contours.y * 0.7, cfg.contours.y * 0.7 + 0.8, majorDistance);
  if (theme.mode.x > 0.5) {
    let paper = mix(lightPaper(), lightGold(), 0.025);
    let ink = mix(lightEmerald(), lightBlue(), smoothstep(0.25, 0.85, height));
    let minorColor = mix(paper, ink, line * 0.9);
    let color = mix(minorColor, lightInk(), major);
    let fade = select(1.0, smoothstep(0.0, 0.65, uv.x), cfg.options.y > 0.5);
    return vec4f(mix(paper, color, fade), 1.0);
  }
  let paper = cfg.background.rgb;
  let contourInk = palette(height);
  let color = mix(paper, contourInk, max(line * 0.35, major * 0.7));

  let fade = select(1.0, smoothstep(0.0, 0.65, uv.x), cfg.options.y > 0.5);
  return vec4f(mix(paper, color, fade), 1.0);
}

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
export fn lightInk() -> vec3f { return vec3f(0.0666667, 0.2352941, 0.1960784); }
export fn lightEmerald() -> vec3f { return vec3f(0.0000000, 0.4862745, 0.3450980); }
export fn lightCyan() -> vec3f { return vec3f(0.0000000, 0.5450980, 0.7215686); }
export fn lightBlue() -> vec3f { return vec3f(0.1568627, 0.3686275, 0.9098039); }
export fn lightViolet() -> vec3f { return vec3f(0.5098039, 0.2666667, 0.8470588); }
export fn lightRose() -> vec3f { return vec3f(0.8392157, 0.2352941, 0.5137255); }
export fn lightGold() -> vec3f { return vec3f(0.8431373, 0.5764706, 0.1137255); }
